function show(p){$$('.page').forEach(x=>x.classList.toggle('active-page',x.id===p));$$('.nav[data-page]').forEach(x=>x.classList.toggle('active',x.dataset.page===p));const n={dashboard:['OVERVIEW','Selamat pagi, Rifqi'],attendance:['OPERASIONAL','Absensi'],work:['OPERASIONAL','Laporan pekerjaan'],server:['INFRASTRUKTUR','Pengecekan server'],reimburse:['KEUANGAN','Reimbursement'],request:['PENGADAAN','Pengajuan barang'],monthly:['REKAP','Laporan bulanan'],settings:['SISTEM','Pengaturan']};$('#crumb').textContent=n[p][0];$('#pageTitle').textContent=n[p][1];scrollTo(0,0)}function toast(t){$('#toast').textContent=t;$('#toast').classList.remove('hidden');setTimeout(()=>$('#toast').classList.add('hidden'),2600)}
function printDoc(m){if(m==='monthly'){print();return}const rooms={'server-lantai5':'Lantai 5','server-r610':'R.610 Kaca'},room=rooms[m]||'',module=room?'server':m,labels={attendance:'Absensi',work:'Laporan Pekerjaan',server:'Pengecekan Suhu Ruang Server',reimburse:'Surat Permohonan Reimbursement',request:'Pengajuan Barang'};if(!labels[module])return toast('Pilih modul laporan yang ingin dicetak terlebih dahulu.');const source=$('#'+module)?.querySelector('table'),w=open('','_blank','width=900,height=700');if(!w)return toast('Izinkan pop-up browser untuk mencetak laporan.');const copy=source.cloneNode(true);copy.querySelectorAll('tbody tr').forEach(tr=>{if(room&&!tr.children[1]?.textContent.includes(room))tr.remove()});copy.querySelectorAll('tr').forEach(tr=>{tr.lastElementChild?.remove();if(['reimburse','request'].includes(module))tr.children[5]?.remove()});let body=copy.outerHTML;if(module==='reimburse')body=`<p>Kepada Yth.<br><b>Manajer terkait</b></p><p>Berikut rincian pengajuan reimbursement periode November 2026.</p>${body}<p>Demikian pengajuan ini dibuat untuk dapat diproses.</p><p style="text-align:right;margin-top:42px">Pemohon,<br><br><br><b>Rifqi Muhammad Athallah</b></p>`;const title=room?`${labels[module]} — ${room}`:labels[module];w.document.write(`<!doctype html><title>${title}</title><style>body{font-family:Arial;color:#111;margin:34px}header{border-bottom:2px solid #172b4d;padding-bottom:12px;margin-bottom:22px}h1{font-size:21px;margin:0}p{font-size:13px;line-height:1.5}table{border-collapse:collapse;width:100%;font-size:11px}th,td{border:1px solid #555;padding:8px;text-align:left;vertical-align:top}th{background:#e9edf2}img{max-height:30px;max-width:70px}@page{size:A4 portrait;margin:14mm}</style><header><h1>${title}</h1><p>Periode November 2026<br>Dicetak: ${new Date().toLocaleDateString('id-ID')}</p></header>${body}`);w.document.close();w.onafterprint=()=>setTimeout(()=>w.close(),150);setTimeout(()=>w.print(),250)}
function input(l,t,v=''){return `<label>${l}<input type="${t}" value="${esc(v)}" required></label>`}function toInput(v=''){if(/^\d{2}\/\d{2}\/\d{4}$/.test(v)){const[a,b,c]=v.split('/');return `${c}-${b}-${a}`}const m=v.match(/(\d{1,2})\s+(\w+)\s+(\d{4})/);if(!m)return '';const mo={Jan:0,Feb:1,Mar:2,Apr:3,Mei:4,Jun:5,Jul:6,Agu:7,Sep:8,Okt:9,Nov:10,Des:11}[m[2].slice(0,3)]??10;return `${m[3]}-${String(mo+1).padStart(2,'0')}-${m[1].padStart(2,'0')}`}function human(v){if(!v)return '';const[y,m,d]=v.split('-');return `${d} ${['Jan','Feb','Mar','Apr','Mei','Jun','Jul','Agu','Sep','Okt','Nov','Des'][Number(m)-1]} ${y}`}
