function detailedMonthlyReport(){const full=$('#monthlyFull');if(!full)return;const stored=localStorage.getItem('monthly-detailed-report');const table=()=>`<table class="formal-table" contenteditable="true"><thead><tr><th>Bulan</th><th>Tanggal</th><th>Kategori</th><th>Judul</th><th>Detail Permasalahan</th><th>Solusi</th></tr></thead><tbody>${data.work.map(r=>`<tr><td>Sep26</td>${r.map(x=>`<td>${esc(x)}</td>`).join('')}</tr>`).join('')}</tbody></table>`;const image=t=>`<div class="image-slot"><label>${t}<input type="file" accept="image/*"></label><img alt="Dokumentasi"></div>`;const page=(body,n)=>`<section class="formal-page">${body}<footer>${n} | Page</footer></section>`;const section=(title,body,n,pic)=>page(`<h2 class="section-heading" contenteditable="true">${title}</h2><div class="formal-underline left"></div>${pic?image('Unggah gambar atau diagram'):''}<div class="editable-body" contenteditable="true">${body}</div>${table()}<p class="caption" contenteditable="true">Tabel ${n}. Index Pekerjaan</p>`,n+3);const doc=`<article id="monthlyDetailedDocument" class="formal-report"><section class="formal-page cover-page"><div class="cover-accent"><i></i><b></b></div><h1 contenteditable="true">LAPORAN BULANAN</h1><p class="cover-period" contenteditable="true">SEPTEMBER 2026</p><div class="cover-spacer" contenteditable="true">&nbsp;</div><div class="cover-accent"><i></i><b></b></div><h2 contenteditable="true">ACCESS CONTROL, CCTV, NETWORK,<br>SERVER AND VOIP</h2><div class="cover-meta" contenteditable="true"><b>DIBUAT OLEH</b><br>TEAM MANAGEMENT SERVICE – IT SUPPORT<br><br><b>PERWAKILAN</b><br>RIFQI MUHAMMAD ATHALLAH</div><footer>1 | Page</footer></section>${page(`<h2 class="formal-heading" contenteditable="true">KATA PENGANTAR</h2><div class="formal-underline"></div><div class="intro-text" contenteditable="true"><p>Dengan rahmat Tuhan Yang Maha Esa, kami selaku <i>Team Management Service</i> telah merampungkan pekerjaan pada bulan September 2026. Dengan ini kami menyerahkan laporan dari setiap pengecekan yang sudah dilakukan pada bulan September 2026.</p><p>Terimakasih atas waktunya, kami ucapkan terimakasih banyak.</p></div><div class="sign-grid" contenteditable="true"><div>Pelaksana Pekerjaan Lapangan<br><br><br><br>Rifqi Muhammad Athallah<br><i>Team Management Service</i><br>Tgl : ...........................</div><div>Peninjau Ulang Pekerjaan<br><br><br><br>Yuna Sukmana<br><i>Team Management Service</i><br>Tgl : ...........................</div></div><div class="knowing" contenteditable="true">Mengetahui,<br><br><br><br>Aris Budi Santoso, S.H.<br>Tgl : ...........................</div>`,2)}${page(`<h2 class="formal-heading" contenteditable="true">DAFTAR ISI</h2><div class="formal-underline"></div><div class="toc" contenteditable="true">KATA PENGANTAR <span>2</span><br>DAFTAR ISI <span>3</span><br><b>A. SERVER I (WIN-UUG431TPVPT)</b> <span>4</span><br>&nbsp;&nbsp;1. Storage Capacity <span>4</span><br>&nbsp;&nbsp;2. Application Installed <span>4</span><br>&nbsp;&nbsp;3. RAM Usage <span>5</span><br>&nbsp;&nbsp;4. Processor Used <span>6</span><br><b>B. SERVER II (WIN-IROTQDKD8F3)</b> <span>7</span><br><b>NETWORK &lt;GPON&gt;</b> <span>10</span><br><b>ACCESS CONTROL</b> <span>12</span><br><b>CCTV Analog dan IP CCTV &lt;CP PLUS&gt;</b> <span>13</span><br><b>VOIP SYSTEM &lt;BRIKERBOX&gt;</b> <span>14</span><br><b>PEKERJAAN LAINNYA</b> <span>16</span></div>`,3)}${section('SERVER',`<h3>A. SERVER I (WIN-UUG431TPVPT)</h3><h4>1. Storage Capacity</h4><p><b>**Keterangan :</b><br>1. LOCAL DISK C — Used Disk dan Free Disk dapat diisi di sini.<br>2. LOCAL DISK D — Data backup dan kapasitas tersedia dapat diisi di sini.</p><h4>2. Application Installed</h4><p>Masukkan daftar aplikasi pada server I.</p><h4>3. RAM Usage</h4><p>Masukkan hasil pemeriksaan penggunaan RAM.</p><h4>4. Processor Used</h4><p>Masukkan hasil pemeriksaan penggunaan prosesor.</p>`,1,true)}${section('SERVER II',`<h3>B. SERVER II (WIN-IROTQDKD8F3)</h3><h4>1. Storage Capacity</h4><p>Isi kapasitas Local Disk C dan Local Disk D.</p><h4>2. Application Installed</h4><p>Masukkan aplikasi terinstal dan hasil pemeriksaannya.</p><h4>3. RAM Used</h4><p>Masukkan hasil penggunaan RAM.</p><h4>4. Processor Used</h4><p>Masukkan hasil penggunaan prosesor.</p>`,2,true)}${section('NETWORK &lt;GPON&gt;',`<h3>A. Temperature Perangkat</h3><ol><li><b>Temperature OLT</b><br>OLT-BTS# show start temp<br>Temperature current : 41 C<br>Temperature threshold : High (80 C) Low (-20 C)</li><li><b>Temperature ONU Lt. 5-1 [I-NET]</b><br>Masukkan hasil pemeriksaan suhu ONU.</li><li><b>Temperature ONU Lt. 5-2 [TELP]</b><br>Masukkan hasil pemeriksaan suhu ONU.</li><li><b>Temperature ONU Lt. 1 [CCTV]</b><br>Masukkan hasil pemeriksaan suhu ONU.</li><li><b>B. Daftar Pekerjaan / Perbaikan</b></li></ol>`,3,false)}${section('ACCESS CONTROL',`<h3>A. InBio 460 Pro – ZKTeco</h3><p>Seluruh InBio Lantai 6, Lantai 3, Lantai 2, dan Lantai Dasar aktif normal.</p><h3>B. Fingerprint Data Record</h3><p>Masukkan hasil pemeriksaan data fingerprint dan perbaikan.</p><h3>C. Daftar Pekerjaan / Perbaikan</h3>`,4,true)}${section('CCTV Analog dan IP CCTV &lt;CP PLUS&gt;',`<h3>A. CCTV Analog dan IP – CCTV</h3><p>Total ada 31 IP CCTV yang aktif dan CCTV Analog berjumlah 12 titik yang aktif.</p><h3>B. Daftar Pekerjaan / Perbaikan</h3>`,5,true)}${section('VOIP SYSTEM &lt;BRIKERBOX&gt;',`<h3>A. Daftar Pekerjaan / Perbaikan</h3><p>Masukkan hasil pemeriksaan Brikerbox, telepon, dan perangkat VoIP.</p>`,6,true)}${section('PEKERJAAN LAINNYA',`<p>Masukkan aktivitas pekerjaan lain yang dilakukan pada periode laporan.</p>`,7,false)}</article>`;full.innerHTML=`<div class="detailed-editor"><b>Editor laporan lengkap</b><span>Semua teks dan setiap sel tabel dapat langsung diubah. Unggah gambar pada area dokumentasi.</span><button class="primary" id="saveDetailedReport">Simpan perubahan</button><button class="outline" id="resetDetailedReport">Kembalikan template</button></div>${stored||doc}`;full.querySelectorAll('.image-slot input').forEach(i=>i.onchange=()=>{const f=i.files[0],img=i.closest('.image-slot').querySelector('img');if(f){const r=new FileReader();r.onload=()=>{img.src=r.result;img.classList.add('uploaded')};r.readAsDataURL(f)}});$('#saveDetailedReport').onclick=()=>{localStorage.setItem('monthly-detailed-report',$('#monthlyDetailedDocument').outerHTML);toast('Laporan lengkap tersimpan.');};$('#resetDetailedReport').onclick=()=>{localStorage.removeItem('monthly-detailed-report');detailedMonthlyReport()}}
detailedMonthlyReport();
function upgradeDocumentEditor(){const full=$('#monthlyFull'),report=$('#monthlyDetailedDocument'),bar=full?.querySelector('.detailed-editor');if(!full||!report||!bar||$('#wordToolbar'))return;report.contentEditable='true';report.setAttribute('spellcheck','true');bar.insertAdjacentHTML('afterbegin',`<div id="wordToolbar" class="word-toolbar"><label>Periode <select id="reportMonth">${['Januari','Februari','Maret','April','Mei','Juni','Juli','Agustus','September','Oktober','November','Desember'].map(m=>`<option ${m==='September'?'selected':''}>${m}</option>`).join('')}</select><select id="reportYear">${[2025,2026,2027,2028].map(y=>`<option ${y===2026?'selected':''}>${y}</option>`).join('')}</select></label><span></span><button type="button" data-command="bold"><b>B</b></button><button type="button" data-command="italic"><i>I</i></button><button type="button" data-command="underline"><u>U</u></button><button type="button" data-command="justifyLeft">≡</button><button type="button" data-command="insertUnorderedList">• List</button><button type="button" data-action="heading">+ Judul</button><button type="button" data-action="paragraph">+ Teks</button><button type="button" data-action="table">+ Tabel</button><button type="button" data-action="photo">+ Foto</button><button type="button" data-action="page">+ Halaman</button><button type="button" data-action="toc">↻ Daftar isi</button><input id="wordImageUpload" type="file" accept="image/*" hidden></div>`);const period=()=>`${$('#reportMonth').value.toUpperCase()} ${$('#reportYear').value}`;const saveRange=()=>{const s=getSelection();if(s?.rangeCount)full._range=s.getRangeAt(0)};full.addEventListener('mouseup',saveRange);full.addEventListener('keyup',saveRange);const insert=html=>{report.focus();const r=full._range;if(r){r.deleteContents();r.insertNode(r.createContextualFragment(html));r.collapse(false)}else report.insertAdjacentHTML('beforeend',html);numberPages()};const numberPages=()=>report.querySelectorAll('.formal-page').forEach((p,i)=>{p.draggable=true;p.dataset.page=i+1;const f=p.querySelector('footer');if(f)f.textContent=`${i+1} | Page`});const refreshToc=()=>{const list=[...report.querySelectorAll('.section-heading, .formal-page h3')].filter(h=>!h.closest('.cover-page')&&!h.closest('.intro-page')).map(h=>{const pg=h.closest('.formal-page')?.dataset.page||'';return `${h.textContent.trim()} <span>${pg}</span>`}).join('<br>');const toc=[...report.querySelectorAll('.toc')][0];if(toc)toc.innerHTML=list||'Belum ada judul bagian.';toast('Daftar isi diperbarui sesuai urutan halaman.');};const setPeriod=()=>{report.querySelectorAll('.cover-period').forEach(x=>x.textContent=period());report.querySelectorAll('.formal-page h1+h2').forEach(x=>x.textContent=period())};bar.querySelectorAll('[data-command]').forEach(b=>b.onclick=()=>{report.focus();document.execCommand(b.dataset.command,false,null);saveRange()});bar.querySelector('[data-action="heading"]').onclick=()=>insert('<h2 class="section-heading">JUDUL BAGIAN BARU</h2><div class="formal-underline left"></div>');bar.querySelector('[data-action="paragraph"]').onclick=()=>insert('<p>Masukkan teks laporan di sini.</p>');bar.querySelector('[data-action="table"]').onclick=()=>insert('<table class="formal-table"><tbody><tr><th>Kolom 1</th><th>Kolom 2</th><th>Kolom 3</th></tr><tr><td>Data</td><td>Data</td><td>Data</td></tr></tbody></table>');bar.querySelector('[data-action="photo"]').onclick=()=>$('#wordImageUpload').click();bar.querySelector('[data-action="page"]').onclick=()=>{report.insertAdjacentHTML('beforeend','<section class="formal-page"><h2 class="section-heading">HALAMAN BARU</h2><div class="formal-underline left"></div><p>Masukkan isi laporan di sini.</p><footer></footer></section>');numberPages()};bar.querySelector('[data-action="toc"]').onclick=refreshToc;$('#reportMonth').onchange=setPeriod;$('#reportYear').onchange=setPeriod;$('#wordImageUpload').onchange=e=>{const f=e.target.files[0];if(!f)return;const r=new FileReader();r.onload=()=>insert(`<figure class="user-photo"><img src="${r.result}"><figcaption>Gambar / keterangan</figcaption></figure>`);r.readAsDataURL(f)};let dragging=null;report.addEventListener('dragstart',e=>{const p=e.target.closest('.formal-page');if(p){dragging=p;p.classList.add('dragging')}});report.addEventListener('dragover',e=>{e.preventDefault();const p=e.target.closest('.formal-page');if(p&&dragging&&p!==dragging){const rect=p.getBoundingClientRect();p.parentNode.insertBefore(dragging,e.clientY<rect.top+rect.height/2?p:p.nextSibling)}});report.addEventListener('dragend',()=>{dragging?.classList.remove('dragging');dragging=null;numberPages();refreshToc()});numberPages();refreshToc();setPeriod()}
