function installSharedSignatures(){const key='ops-shared-signatures';let assets={};try{assets=JSON.parse(localStorage.getItem(key)||'{}')}catch{}const save=()=>localStorage.setItem(key,JSON.stringify(assets));const img=(src,label)=>src?`<img class="shared-signature" src="${src}" alt="${label}">`:'';const apply=()=>{if(assets.paraf)data.server.forEach(r=>r[6]=assets.paraf);render();const room=$('#monthlyRoom')?.value||'Lantai 5';renderSheet(room);const doc=$('#monthlyDetailedDocument');if(doc){doc.querySelectorAll('.shared-signature').forEach(x=>x.remove());const signs=doc.querySelectorAll('.sign-grid>div');if(signs[0]&&assets.pelaksana)signs[0].insertAdjacentHTML('beforeend',img(assets.pelaksana,'Tanda tangan pelaksana'));if(signs[1]&&assets.approval)signs[1].insertAdjacentHTML('beforeend',img(assets.approval,'Tanda tangan approval'));}};const renderSheet=room=>{const names=['Minggu','Senin','Selasa','Rabu','Kamis','Jumat','Sabtu'];const rows=Array.from({length:30},(_,i)=>{const day=i+1,date=new Date(2026,10,day),r=data.server.find(x=>x[1]===room&&Number(x[0].split('/')[0])===day),weekend=[0,6].includes(date.getDay());return `<tr class="${weekend?'weekend':''}"><td>${day}</td><td>${String(day).padStart(2,'0')}/11/2026</td><td>${names[date.getDay()]}, ${day} November 2026</td><td>${r?.[2]||''}</td><td>${r?.[3]||''}</td><td>${r?.[4]||''}</td><td>${r?.[5]==='Normal'?'✓':''}</td><td></td><td>${paraf(assets.paraf||r?.[6]||'')}</td></tr>`}).join('');if($('#monthlyTemperatureRows'))$('#monthlyTemperatureRows').innerHTML=rows};const settings=$('#settings .settings-grid');if(settings&&!$('#signatureManager'))settings.insertAdjacentHTML('afterbegin','<section class="panel signature-manager" id="signatureManager"><div class="signature-heading"><div><span class="eyebrow">SEKALI UNGGAH</span><h3>Paraf & tanda tangan</h3><p>Satu file berlaku otomatis di seluruh catatan suhu, laporan bulanan, dan dokumen cetak.</p></div><button type="button" class="outline danger" id="clearSignatures">Hapus aset</button></div><div class="signature-upload-grid"><label>Paraf pemeriksa<input type="file" accept="image/png,image/jpeg" data-signature="paraf"><span id="preview-paraf"></span></label><label>Tanda tangan pelaksana<input type="file" accept="image/png,image/jpeg" data-signature="pelaksana"><span id="preview-pelaksana"></span></label><label>Tanda tangan approval<input type="file" accept="image/png,image/jpeg" data-signature="approval"><span id="preview-approval"></span></label></div></section>');const previews=()=>['paraf','pelaksana','approval'].forEach(name=>{const target=$('#preview-'+name);if(target)target.innerHTML=assets[name]?img(assets[name],name):'<em>Belum diunggah</em>'});document.querySelectorAll('[data-signature]').forEach(input=>input.onchange=()=>{const file=input.files?.[0],name=input.dataset.signature;if(!file)return;if(file.size>2*1024*1024)return toast('Ukuran gambar maksimal 2 MB.');const reader=new FileReader();reader.onload=()=>{assets[name]=reader.result;save();previews();apply();toast('Tersimpan dan diterapkan ke seluruh laporan.');};reader.readAsDataURL(file)});$('#clearSignatures')?.addEventListener('click',()=>{if(!confirm('Hapus semua paraf dan tanda tangan yang tersimpan?'))return;assets={};save();previews();apply();toast('Aset paraf dan tanda tangan dihapus.');});$('#monthlyRoom')?.addEventListener('change',e=>renderSheet(e.target.value));const print=$('#monthlyPrint');if(print)print.onclick=()=>{const room=$('#monthlyRoom')?.value||'Lantai 5';const rows=Array.from({length:30},(_,i)=>{const day=i+1,date=new Date(2026,10,day),r=data.server.find(x=>x[1]===room&&Number(x[0].split('/')[0])===day),weekend=[0,6].includes(date.getDay());return `<tr class="${weekend?'weekend':''}"><td>${day}</td><td>${String(day).padStart(2,'0')}/11/2026</td><td>${date.toLocaleDateString('id-ID',{weekday:'long',day:'numeric',month:'long',year:'numeric'})}</td><td>${r?.[2]||''}</td><td>${r?.[3]||''}</td><td>${r?.[4]||''}</td><td>${r?.[5]==='Normal'?'✓':''}</td><td></td><td>${paraf(assets.paraf||r?.[6]||'')}</td></tr>`}).join('');const w=open('','_blank');if(!w)return toast('Izinkan pop-up browser untuk mencetak.');w.document.write(`<style>@page{size:A4 portrait;margin:12mm}body{font:10px Arial;color:#172b4d}h1,p{text-align:center}table{border-collapse:collapse;width:100%}th,td{border:1px solid #334155;padding:5px;text-align:center}.weekend td{background:#ff2020!important}img{max-height:28px;max-width:65px;object-fit:contain}@media print{.weekend td{-webkit-print-color-adjust:exact;print-color-adjust:exact}}</style><h1>Pengecekan Bulanan Suhu Ruang Server</h1><p>${room} · November 2026</p><table><thead><tr><th>No.</th><th>Tanggal</th><th>Hari / Tanggal</th><th>Jam</th><th>Suhu</th><th>Kelembaban</th><th>Normal</th><th>Abnormal</th><th>Paraf</th></tr></thead><tbody>${rows}</tbody></table>`);w.document.close();setTimeout(()=>w.print(),350)};previews();apply()}
setTimeout(installSharedSignatures,1000);
/* Docs/Sheets-inspired workspace controls: outline, ruler, zoom, menus, and table context actions. */
function installEnhancedDocsWorkspace(){const full=$('#monthlyFull'),report=$('#monthlyDetailedDocument'),bar=$('#docsMenuBar'),toolbar=$('#wordToolbar');if(!full||!report||!bar||full.dataset.enhanced)return;full.dataset.enhanced='1';full.classList.add('docs-enhanced');bar.insertAdjacentHTML('afterend','<div id="docsRuler" class="docs-ruler" aria-label="Penggaris dokumen"><span>0</span><span>1</span><span>2</span><span>3</span><span>4</span><span>5</span><span>6</span><span>7</span><span>8</span><span>9</span><span>10</span><span>11</span><span>12</span><span>13</span><span>14</span><span>15</span></div>');const outline=document.createElement('aside');outline.id='docsOutline';outline.className='docs-outline';outline.innerHTML='<div><b>Outline dokumen</b><button type="button" title="Tutup outline">×</button></div><nav></nav>';report.before(outline);const refreshOutline=()=>{outline.querySelector('nav').innerHTML=[...report.querySelectorAll('h1,h2.section-heading,h3')].map((h,i)=>{h.id=h.id||'heading-'+i;return `<button type="button" data-jump="${h.id}" class="level-${h.tagName.toLowerCase()}">${h.textContent.trim().slice(0,48)}</button>`}).join('')||'<small>Tambahkan judul untuk membentuk outline.</small>'};refreshOutline();outline.onclick=e=>{if(e.target.matches('[data-jump]'))document.getElementById(e.target.dataset.jump)?.scrollIntoView({behavior:'smooth',block:'center'});if(e.target.closest('button[title]'))outline.classList.add('hidden')};toolbar.insertAdjacentHTML('afterbegin','<div class="toolbar-group docs-zoom"><select id="docsZoom" aria-label="Zoom"><option value=".85">85%</option><option value="1" selected>100%</option><option value="1.1">110%</option><option value="1.25">125%</option></select></div>');$('#docsZoom').onchange=e=>{report.style.setProperty('--paper-zoom',e.target.value);report.style.transform=`scale(${e.target.value})`;report.style.transformOrigin='top center';report.style.marginBottom=`${(Number(e.target.value)-1)*1040}px`};const choices={File:[['Simpan','save'],['Cetak','print'],['Halaman baru','page'],['Kembali ke template','reset']],Edit:[['Urungkan','undo'],['Ulangi','redo'],['Pilih semua','select'],['Cari & ganti','find']],Tampilan:[['Tampilkan outline','outline'],['Tampilkan penggaris','ruler'],['Mode fokus','focus']],Sisipkan:[['Judul','heading'],['Paragraf','paragraph'],['Tabel','table'],['Gambar','photo'],['Garis horizontal','rule'],['Batas halaman','page'],['Daftar isi','toc']],Format:[['Tebal','bold'],['Miring','italic'],['Garis bawah','underline'],['Rata kiri','justifyLeft'],['Tengah','justifyCenter'],['Rata kanan','justifyRight'],['Justify','justifyFull'],['Daftar berpoin','insertUnorderedList'],['Daftar bernomor','insertOrderedList']],Alat:[['Jumlah kata','words'],['Perbarui outline','outlineRefresh'],['Perbarui daftar isi','toc'],['Paraf & tanda tangan','signatures']],Bantuan:[['Pintasan keyboard','shortcuts'],['Panduan tabel','tableHelp']]};let panel=$('#docsActions');if(!panel){panel=document.createElement('div');panel.id='docsActions';panel.className='docs-actions hidden';bar.appendChild(panel)}const run=a=>{const cmd=['undo','redo','bold','italic','underline','justifyLeft','justifyCenter','justifyRight','justifyFull','insertUnorderedList','insertOrderedList'].includes(a)?a:null;if(cmd){report.focus();document.execCommand(cmd,false,null)}else if(a==='save')$('#saveDetailedReport')?.click();else if(a==='print')bar.querySelector('.docs-print')?.click();else if(a==='page')toolbar.querySelector('[data-action="page"]')?.click();else if(a==='heading'||a==='paragraph'||a==='table'||a==='photo')toolbar.querySelector(`[data-action="${a}"]`)?.click();else if(a==='rule'){document.execCommand('insertHorizontalRule');}else if(a==='toc')toolbar.querySelector('[data-action="toc"]')?.click();else if(a==='outline'){outline.classList.toggle('hidden')}else if(a==='ruler')$('#docsRuler')?.classList.toggle('hidden');else if(a==='focus')document.body.classList.toggle('document-focus');else if(a==='outlineRefresh'){refreshOutline();toast('Outline dokumen diperbarui.')}else if(a==='signatures'){show('settings');setTimeout(()=>$('#signatureManager')?.scrollIntoView({behavior:'smooth'}),100)}else if(a==='select'){const r=document.createRange(),s=getSelection();r.selectNodeContents(report);s.removeAllRanges();s.addRange(r)}else if(a==='find'){const find=prompt('Cari teks:'),replace=find!==null?prompt('Ganti dengan:',''):null;if(find&&replace!==null){report.innerHTML=report.innerHTML.split(find).join(replace);toast('Teks diperbarui.')}}else if(a==='words'){toast(`Jumlah kata: ${report.innerText.trim().split(/\s+/).filter(Boolean).length}`)}else if(a==='shortcuts'){toast('Ctrl+B tebal · Ctrl+I miring · Ctrl+U garis bawah · Ctrl+E tengah · Ctrl+J justify · Tab berpindah sel.')}else if(a==='tableHelp'){toast('Klik sel tabel untuk menampilkan operasi tambah/hapus baris & kolom, gabungkan, dan pisahkan sel.')}else if(a==='reset')confirm('Kembalikan dokumen ke template?')&&$('#resetDetailedReport')?.click();refreshOutline();panel.classList.add('hidden')};bar.querySelectorAll('[data-docs-menu]').forEach(b=>{if(b.dataset.docsMenu==='Print')return;b.onclick=e=>{e.stopPropagation();const list=choices[b.dataset.docsMenu]||[];panel.innerHTML=list.map(([label,a])=>`<button type="button" data-doc-action="${a}">${label}</button>`).join('');const r=b.getBoundingClientRect(),h=bar.getBoundingClientRect();panel.style.left=(r.left-h.left)+'px';panel.classList.remove('hidden')}});panel.onclick=e=>e.target.dataset.docAction&&run(e.target.dataset.docAction);document.addEventListener('click',e=>{if(!bar.contains(e.target))panel.classList.add('hidden')});report.addEventListener('contextmenu',e=>{const cell=e.target.closest('td,th');if(!cell)return;e.preventDefault();const old=$('#sheetContext');old?.remove();const menu=document.createElement('div');menu.id='sheetContext';menu.className='sheet-context';menu.style.left=e.clientX+'px';menu.style.top=e.clientY+'px';menu.innerHTML='<b>Operasi tabel</b><button data-proxy="rowAbove">Sisipkan baris di atas</button><button data-proxy="rowBelow">Sisipkan baris di bawah</button><button data-proxy="colLeft">Sisipkan kolom kiri</button><button data-proxy="colRight">Sisipkan kolom kanan</button><button data-proxy="merge">Gabungkan sel</button><button data-proxy="deleteRow">Hapus baris</button><button data-proxy="deleteCol">Hapus kolom</button>';document.body.appendChild(menu);menu.onclick=x=>{const action=x.target.dataset.proxy;if(action){document.querySelector(`.table-tools [data-table="${action}"]`)?.click();menu.remove()}};setTimeout(()=>document.addEventListener('click',()=>menu.remove(),{once:true}),0)});}
setTimeout(installEnhancedDocsWorkspace,1400);
